describe('Sauce Demo Login', () => {
  beforeEach(() => {
    cy.visit('https://www.saucedemo.com');
  });

  it('should successfully log in with valid credentials and redirect to inventory page', () => {
    cy.get('[data-test="username"]').should('be.visible').type('standard_user');
    cy.get('[data-test="password"]').should('be.visible').type('secret_sauce');
    cy.get('[data-test="login-button"]').should('be.visible').click();

    cy.url().should('include', '/inventory.html');
    cy.get('.title').should('be.visible').and('have.text', 'Products');
  });

  it('should display login form elements with correct data-test attributes', () => {
    cy.get('[data-test="username"]').should('exist').and('be.visible');
    cy.get('[data-test="password"]').should('exist').and('be.visible');
    cy.get('[data-test="login-button"]').should('exist').and('be.visible');
  });

  it('should show error message when logging in with invalid credentials', () => {
    cy.get('[data-test="username"]').type('invalid_user');
    cy.get('[data-test="password"]').type('wrong_password');
    cy.get('[data-test="login-button"]').click();

    cy.url().should('not.include', '/inventory.html');
    cy.get('[data-test="error"]').should('be.visible');
  });

  it('should remain on login page when credentials are empty', () => {
    cy.get('[data-test="login-button"]').click();

    cy.url().should('not.include', '/inventory.html');
    cy.get('[data-test="username"]').should('be.visible');
  });
});
